function result=runV4BValidationControlledPass(passIndex)
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();x=load(fullfile(root,'results','calibration','track_b','B-param-v01','calibration.mat'),'artifact');p=x.artifact.parameters;schedule=v4ContinuousPassSchedule(c);state=struct('time',schedule.passStartTimeSec,'phase',0,'cross',struct());errors=zeros(3,4,3);counts=zeros(4,3);vpAccepted=zeros(3,1);vpFalse=zeros(3,1);frames=zeros(3,1);
for fi=1:schedule.frameCount,offset=(passIndex-1)*5000+fi;ledger=struct('payloadSeed',1200000000+offset,'noiseSeed',1300000000+offset,'channelSeed',1400000000+offset,'scope','b_validation_controlled','snrIndex',1,'passIndex',passIndex,'frameIndex',fi);frame=v4GenerateContinuousFrame(c,state.time,-21,ledger,state.phase,'AWGN');state.time=frame.nextFrameStartTimeSec;state.phase=frame.nextFrameStartPhaseRad;if ~schedule.metricEligible(fi),state.cross=struct();continue,end;trajectory=v4Trajectory(schedule.frameCenterTimeSec(fi),c);elevation=rad2deg(trajectory.elevationRad);region=1+(elevation>=30);regions=[region 3];b=v4CommonBootstrap(frame.observation.rxPhysical(1:8,:),c,SearchStepBins=p.searchStepBins);robust=v4BIndividualPreambleRate(frame.observation.rxPhysical(1:8,:),c,p.searchStepBins);measurement=schedule.frameStartTimeSec(fi)+4*c.symbolDurationSec;[rate,state.cross]=v4CrossFrameRateUpdate(state.cross,measurement,mean(b.cfoBins),robust.rateBinsPerSec,c,p);rx={v4HuangStaticDecode(frame.observation,b,c),v4Stage55Decode(frame.observation,b,c,p,CrossFrameRateBinsPerSec=rate,CrossFrameHistoryCount=state.cross.historyCount),v4PaperMidambleDecode(frame.observation,b,c,p)};for r=regions,counts(:,r)=counts(:,r)+[112;768;768;1];frames(r)=frames(r)+1;for method=1:3,m=v4EvaluateFrame(rx{method},frame.truth,c);errors(method,:,r)=errors(method,:,r)+[m.symbolErrors m.hardBitErrors m.softBitErrors m.packetError];end;mask=rx{2}.virtualPilotAccepted;vpAccepted(r)=vpAccepted(r)+sum(mask);vpFalse(r)=vpFalse(r)+sum(mask&rx{2}.detectedPhysicalBins~=frame.truth.payloadPhysicalBins);end;end
metrics=zeros(size(errors));for r=1:3,for method=1:3,metrics(method,:,r)=reshape(errors(method,:,r),1,4)./counts(:,r).';end,end;result=struct('status','PASS','passIndex',passIndex,'channel','AWGN','mode','controlled-time','snrDb',-21,'algorithmVersion','Stage55-B-project-path-calibrated-v7','rawErrors',errors,'denominators',counts,'metrics',metrics,'vpAccepted',vpAccepted,'vpFalseAccepted',vpFalse,'frames',frames,'conditionsFrozen',true);folder=fullfile(root,'results','validation','track_b','controlled_awgn','B-param-v01','passes');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,sprintf('pass_%02d.mat',passIndex)),'result','-v7.3');write(fullfile(folder,sprintf('pass_%02d.json',passIndex)),jsonencode(result,'PrettyPrint',true));fprintf('B validation controlled pass %d complete\n',passIndex);
end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
